class AppError(Exception):
    status = 500
class NotFound(AppError):
    status = 404
class OrderNotFound(NotFound):
    pass
class Conflict(AppError):
    status = 409

handlers = {NotFound: "not_found_handler", AppError: "app_error_handler"}

def find_handler(exc):
    for cls in type(exc).__mro__:
        if cls in handlers:
            return handlers[cls]
    return "500 default"

for exc in [OrderNotFound(), Conflict(), KeyError()]:
    print(type(exc).__name__, getattr(exc, "status", "-"), find_handler(exc))

